def read_rows(opening):
    rows = opening["rows"]
    if type(rows) is not list:
        raise ValueError("/opening/rows", "*{Row}", "other")
    for i, row in enumerate(rows):
        if i == 4096:
            raise ValueError("/opening/rows/4096", "at most 4096 items", "extra item")
        if type(row) is not dict:
            raise ValueError(f"/opening/rows/{i}", "{Row}", "other")
        for field in ("sequence", "balance"):
            if field not in row:
                raise ValueError(f"/opening/rows/{i}/{field}", "i", "missing")
            value = row[field]
            if type(value) is not int or not -(1 << 63) <= value < (1 << 63):
                actual = "string" if type(value) is str else "other"
                raise ValueError(f"/opening/rows/{i}/{field}", "i", actual)
        if len(row) != 2:
            raise ValueError(f"/opening/rows/{i}", "{Row}", "extra field")
    return rows
